import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var i=JSON.parse(`{"title":"Settings","description":"","frontmatter":{"prev":{"text":"Icon","link":"/documentation/icon"},"next":{"text":"Logs","link":"/documentation/logs"}},"headers":[],"relativePath":"documentation/settings.md","filePath":"documentation/settings.md","lastUpdated":1788551488000}`),a={name:`documentation/settings.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to “Settings”">​</a></h1><p>The Settings page provides comprehensive control over the Excellent Data Filler extension&#39;s behavior, allowing you to customize its functionality according to your specific needs and preferences.</p><img src="/image/extension-settings-01.png" width="700" height="500" alt="Extension Settings Interface"><h2 id="extension-settings" tabindex="-1"><img src="/svg/settings.svg" class="doc-icon" width="22" height="22" alt="Extension Settings"> Extension Settings <a class="header-anchor" href="#extension-settings" aria-label="Permalink to “Extension Settings”">​</a></h2><p>Control global extension behavior and automation power state.</p><h3 id="extension-control" tabindex="-1">Extension Control <a class="header-anchor" href="#extension-control" aria-label="Permalink to “Extension Control”">​</a></h3><p>The master switch governing all extension activity across your browser.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>Extension Active Status</strong></td><td>Toggle</td><td>Turn automatic filling and extension detection on or off globally.</td></tr></tbody></table><p><strong>Key Details:</strong></p><ul><li><strong>Turn ON / OFF</strong>: When toggled OFF, all automated form detection, page-load triggers, and data entry routines are paused globally.</li><li><strong>Keyboard Shortcut</strong>: Press <kbd>Alt</kbd> + <kbd>Q</kbd> anywhere in your browser to instantly toggle the extension status on or off.</li><li><strong>Visual Feedback</strong>: The browser toolbar icon dynamically reflects status (vibrant colored icon = <strong>ON</strong>, grayscale icon = <strong>OFF</strong>).</li></ul><div class="info custom-block"><p class="custom-block-title">Customize Shortcuts</p><p>You can customize shortcut key combinations in Chrome anytime by visiting <code>chrome://extensions/shortcuts</code>.</p></div><hr><h2 id="dialog-boxes" tabindex="-1"><img src="/svg/chat.svg" class="doc-icon" width="22" height="22" alt="Dialog Boxes"> Dialog Boxes <a class="header-anchor" href="#dialog-boxes" aria-label="Permalink to “Dialog Boxes”">​</a></h2><p>Manage auto-dismissal rules and automated responses for JavaScript dialog popups (<code>alert</code> and <code>confirm</code>) to ensure smooth, unattended automation.</p><h3 id="dialog-management" tabindex="-1">Dialog Management <a class="header-anchor" href="#dialog-management" aria-label="Permalink to “Dialog Management”">​</a></h3><p>Configure automated rules for alert popups and confirmation prompts.</p><h4 id="alert-dialogs" tabindex="-1">Alert Dialogs <a class="header-anchor" href="#alert-dialogs" aria-label="Permalink to “Alert Dialogs”">​</a></h4><p>Automatically dismiss JavaScript <code>alert()</code> popups without requiring manual user intervention.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>Hide Alert Dialogs</strong></td><td>Toggle</td><td>Automatically dismiss JavaScript <code>alert()</code> popups without user action.</td></tr><tr><td><strong>Target URLs for Alert Dismissal</strong></td><td>URL List</td><td>Enter website URLs and press <kbd>Enter</kbd> to add them to the dismissal list.</td></tr></tbody></table><p><strong>How It Works:</strong></p><ol><li>Toggle <strong>Hide Alert Dialogs</strong> to <strong>ON</strong>.</li><li>Enter your target website URL(s) into <strong>Target URLs for Alert Dismissal</strong> and press <kbd>Enter</kbd>.</li><li>When an <code>alert()</code> appears on the specified site, the extension automatically intercepts and dismisses it immediately in the background so form automation continues without interruption.</li></ol><h4 id="confirm-dialogs" tabindex="-1">Confirm Dialogs <a class="header-anchor" href="#confirm-dialogs" aria-label="Permalink to “Confirm Dialogs”">​</a></h4><p>Automatically answer JavaScript <code>confirm()</code> dialogs with predefined affirmative or negative decisions.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>Hide Confirm Dialogs</strong></td><td>Toggle</td><td>Automatically answer <code>confirm()</code> dialogs with predefined decisions.</td></tr><tr><td><strong>Target URLs for Confirm Dismissal</strong></td><td>URL List</td><td>Enter website URLs where confirmation dialogs should be automatically answered.</td></tr><tr><td><strong>Match Message Text Patterns</strong></td><td>Text Patterns</td><td>(Optional) Specify keyword patterns inside confirm dialogs to target specific prompts.</td></tr><tr><td><strong>Choose Default Action</strong></td><td>Action Option</td><td>Predefine whether to automatically accept (<code>OK</code>) or dismiss (<code>Cancel</code>) the prompt.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Unattended Automation</p><p>If automated form submission triggers an alert or confirmation prompt verifying that an entry has been completed, registering the site URL under <strong>Dialog Management</strong> prevents your automation workflow from pausing.</p></div><hr><h2 id="insert-site-form" tabindex="-1"><img src="/svg/form.svg" class="doc-icon" width="22" height="22" alt="Insert Site / Form Rules"> Insert Site / Form Rules <a class="header-anchor" href="#insert-site-form" aria-label="Permalink to “Insert Site / Form Rules”">​</a></h2><p>Configure DOM detection depth, selector generation strategies, advanced parsing filters, and automatic field label cleaning.</p><h3 id="form-detection" tabindex="-1">Form Detection &amp; Field Rules <a class="header-anchor" href="#form-detection" aria-label="Permalink to “Form Detection &amp; Field Rules”">​</a></h3><p>Fine-tune how the extension scans, detects, and generates selectors for form elements on a web page.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Description</th><th>Default / Options</th></tr></thead><tbody><tr><td><strong>Form Label Position</strong></td><td>Number</td><td>Sets the relative DOM traversal depth and position used to locate field label text.</td><td><code>3</code></td></tr><tr><td><strong>Ignored HTML Tags</strong></td><td>Tag List</td><td>Specify HTML tags to ignore during form scanning (e.g., <code>textarea</code>, <code>select</code>).</td><td>None</td></tr><tr><td><strong>Ignored Input Types</strong></td><td>Tag List</td><td>Specify input types to ignore during detection.</td><td><code>hidden</code>, <code>reset</code></td></tr><tr><td><strong>Preferred Selector Strategy</strong></td><td>Dropdown</td><td>Choose the primary algorithm for generating element selector queries.</td><td><code>Unique CSS Hierarchy</code></td></tr></tbody></table><h4 id="preferred-selector-strategy-options" tabindex="-1">Preferred Selector Strategy Options <a class="header-anchor" href="#preferred-selector-strategy-options" aria-label="Permalink to “Preferred Selector Strategy Options”">​</a></h4><table tabindex="0"><thead><tr><th>Strategy</th><th>Description</th></tr></thead><tbody><tr><td><strong>Unique CSS Hierarchy</strong></td><td>Generates the most concise, unique CSS selector hierarchy that targets the specific element without unnecessary parent selectors.</td></tr><tr><td><strong>Full CSS Path</strong></td><td>Generates the complete CSS selector path from the document root down to the element.</td></tr><tr><td><strong>Full Div Hierarchy</strong></td><td>Generates a structured CSS path specifically tracing through parent container <code>&lt;div&gt;</code> layers.</td></tr><tr><td><strong>XPath Expression</strong></td><td>Generates robust, standard XPath expressions for precise element location.</td></tr></tbody></table><h3 id="advanced-options" tabindex="-1">Advanced Parsing Filters <a class="header-anchor" href="#advanced-options" aria-label="Permalink to “Advanced Parsing Filters”">​</a></h3><p>Enhance DOM scanning resilience for single-page applications (SPAs), modern dynamic frameworks, and secured pages.</p><table tabindex="0"><thead><tr><th>Filter Option</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>Detect Inputs Outside <code>&lt;form&gt;</code></strong></td><td>Toggle</td><td>Scans independent container <code>&lt;div&gt;</code> blocks or modern SPA inputs that are not wrapped within standard HTML <code>&lt;form&gt;</code> tags.</td></tr><tr><td><strong>Check External Libraries</strong></td><td>Toggle</td><td>Detects and utilizes third-party DOM helper scripts if needed during page inspection.</td></tr><tr><td><strong>Only Target Visible Forms</strong></td><td>Toggle</td><td>Ignores hidden or <code>display: none</code> form containers during automatic detection.</td></tr><tr><td><strong>Only Target Visible Input Fields</strong></td><td>Toggle</td><td>Skips invisible, collapsed, or zero-height form elements.</td></tr><tr><td><strong>Allow Right-Click</strong></td><td>Toggle</td><td>Re-enables the browser context menu on websites that disable right-click interactions.</td></tr><tr><td><strong>Force Allow Right-Click</strong></td><td>Toggle</td><td>Strictly overrides hostile JavaScript event handlers blocking right-click access.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Quick Right-Click Bypass via Toolbar Menu</p><p>You can also toggle right-click re-enabling on the active page on the fly: right-click the extension icon in your browser toolbar and click <a href="/documentation/extension/context-menu.html#allow-right-click">Allow Right Click?</a>.</p></div><h3 id="field-name-cleaning" tabindex="-1">Clean Field Names <a class="header-anchor" href="#field-name-cleaning" aria-label="Permalink to “Clean Field Names”">​</a></h3><p>Automatically sanitize and format detected field labels by stripping framework noise, ASP.NET IDs, and unwanted prefixes.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>Clean Field Names</strong></td><td>Toggle</td><td><strong>Master Switch</strong>. When enabled, strips unwanted prefixes or special character noise from detected field labels.</td></tr><tr><td><strong>Remove Substrings from Labels</strong></td><td>Tag List</td><td>List of specific noise substrings to remove from detected labels.</td></tr><tr><td><strong>Remove Prefixes from Labels</strong></td><td>Text Input</td><td>Enter specific prefixes to strip from the beginning of labels.</td></tr></tbody></table><p><strong>Example:</strong></p><ul><li><strong>Raw Web Label / ID:</strong> <code>ctl00$ContentPlaceHolder1$txtName</code></li><li><strong>Substrings Removed:</strong> <code>ctl00$ContentPlaceHolder1$</code></li><li><strong>Clean Detected Field Name:</strong> <code>txtName</code></li></ul><hr><h2 id="form-filler" tabindex="-1"><img src="/svg/browser.svg" class="doc-icon" width="22" height="22" alt="Form Filler Settings"> Form Filler Settings <a class="header-anchor" href="#form-filler" aria-label="Permalink to “Form Filler Settings”">​</a></h2><p>Configure automation speed, status overlay displays, runtime logging viewers, environment variables, CAPTCHA bypass, and web request monitoring.</p><h3 id="visual-feedback" tabindex="-1">Visual Feedback <a class="header-anchor" href="#visual-feedback" aria-label="Permalink to “Visual Feedback”">​</a></h3><p>Configure visual cues, status overlays, and runtime logging during automated filling cycles.</p><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>Input Color Feedback</strong></td><td>Toggle</td><td>Highlight input field backgrounds dynamically during fill cycles to visually track active elements.</td></tr><tr><td><strong>Show Automation Status Bar</strong></td><td>Toggle</td><td>Display a floating overlay status bar during autofill runs.</td></tr><tr><td><strong>Show Log Messages in Status Bar</strong></td><td>Toggle</td><td>Output live execution step messages directly on the status bar. When turned <strong>ON</strong>, log messages are visible in the status bar and attached popover; otherwise, they are not visible.</td></tr><tr><td><strong>Show Extension Logs Viewer</strong></td><td>Toggle</td><td>Show a floating sidebar button on the web page to inspect live runtime log traces and debugging events.</td></tr></tbody></table><h4 id="automation-status-bar" tabindex="-1">Automation Status Bar <a class="header-anchor" href="#automation-status-bar" aria-label="Permalink to “Automation Status Bar”">​</a></h4><p>When <strong>Show Automation Status Bar</strong> is enabled, an interactive toolbar renders on target web pages providing real-time progress, navigation, and live execution feedback.</p><img src="/image/status-bar-01.png" alt="Automation Status Bar"><div class="info custom-block"><p class="custom-block-title">Mark as Saved</p><p>Clicking the <strong>Mark as Saved</strong> button on the status bar triggers the <a href="/documentation/segment.html#predefine-segment">{MARK AS SAVED}</a> segment for the current entry row if configured in the form.</p></div><p><strong>Key Status Bar Capabilities:</strong></p><ul><li><strong>Slim &amp; Modern Design</strong>: Status bar that is sleek, unobtrusive, and fully mobile-responsive.</li><li><strong>Position &amp; Theme Toggle</strong>: Easily toggle the bar&#39;s position between <strong>Top</strong> and <strong>Bottom</strong>, and switch between <strong>Dark</strong> and <strong>Light</strong> themes for optimal contrast on any website.</li><li><strong>Minimize / Float Dock Mode</strong>: Collapse the full toolbar into a compact floating pill docked at the corner of the screen when unobstructed page visibility is needed.</li><li><strong>Attached Logs Popover</strong>: Clicking on the logs section opens an attached flyout card directly above or below the bar to inspect live runtime execution traces (visible only when <strong>Show Log Messages in Status Bar</strong> is turned ON; otherwise not visible).</li></ul><p><strong>Status Bar Controls &amp; Features:</strong></p><table tabindex="0"><thead><tr><th>Control</th><th>Description</th></tr></thead><tbody><tr><td><strong>Current Entry Index</strong></td><td>Displays the current active row number and total rows count (e.g. <code>Entry: 5 / 100</code>).</td></tr><tr><td><strong>Previous Row</strong></td><td>Navigate to and fill the previous data row.</td></tr><tr><td><strong>Next Row</strong></td><td>Navigate to and fill the next data row.</td></tr><tr><td><strong>Mark as Saved</strong></td><td>Executes the <a href="/documentation/segment.html#predefine-segment">{MARK AS SAVED}</a> segment.</td></tr><tr><td><strong>Attached Logs Popover</strong></td><td>Click to open a live flyout card displaying recent execution steps and error logs (visible only when <strong>Show Log Messages in Status Bar</strong> is turned ON; otherwise not visible).</td></tr><tr><td><strong>Dock / Minimize</strong></td><td>Collapses the status bar into a compact floating pill at the corner.</td></tr><tr><td><strong>Position / Theme Toggle</strong></td><td>Switch docking edge (Top/Bottom) or color theme (Dark/Light).</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Close Status Bar Programmatically</p><p>To dismiss or close the status bar from the web page during automation (for example, prior to capturing full-page screenshots or upon finishing form tasks), you can use the <a href="/documentation/functions.html#closestatusbar"><code>closeStatusBar</code></a> predefined function.</p></div><h3 id="show-extension-logs-viewer" tabindex="-1">Show Extension Logs Viewer <a class="header-anchor" href="#show-extension-logs-viewer" aria-label="Permalink to “Show Extension Logs Viewer”">​</a></h3><p>When enabled under <strong>Visual Feedback</strong>, a floating sidebar button appears on active web pages, allowing you to open the dedicated <strong>Extension Logs</strong> runtime viewer directly over the page without opening browser developer tools.</p><img src="/image/logs-viewer.png" alt="Extension Logs Viewer" style="max-width:420px;border-radius:8px;"><h4 id="top-toolbar-controls" tabindex="-1">Top Toolbar Controls <a class="header-anchor" href="#top-toolbar-controls" aria-label="Permalink to “Top Toolbar Controls”">​</a></h4><p>The header bar provides quick actions to control the live log stream and manage records:</p><table tabindex="0"><thead><tr><th>Action</th><th>Description</th></tr></thead><tbody><tr><td><strong>Dock / Sidebar Mode</strong></td><td>Toggle the panel between floating drawer and docked sidebar layouts.</td></tr><tr><td><strong>Search</strong></td><td>Real-time text search to quickly filter logs by keyword, field name, or URL.</td></tr><tr><td><strong>Pause / Resume</strong></td><td>Freeze log streaming to closely inspect a specific event while automation is actively running.</td></tr><tr><td><strong>Download / Export</strong></td><td>Download the current session log records as a file for troubleshooting.</td></tr><tr><td><strong>Clear Logs</strong></td><td>Clears the active log feed from the viewer.</td></tr><tr><td><strong>Close</strong></td><td>Dismisses the slide-over viewer.</td></tr></tbody></table><h4 id="panel-customization" tabindex="-1">Panel Customization <a class="header-anchor" href="#panel-customization" aria-label="Permalink to “Panel Customization”">​</a></h4><p>Customize the viewer to fit your monitor resolution and reading preferences:</p><ul><li><strong>Panel Width Presets</strong>: Select between <strong>420px</strong>, <strong>520px</strong>, <strong>680px</strong>, and <strong>880px</strong> for optimal reading space.</li><li><strong>Zoom Scale</strong>: Adjust text sizing using the zoom controls (<code>-</code>, <code>+</code>, <code>Reset</code>) with percentage scale feedback.</li><li><strong>Theme Mode</strong>: Seamlessly switch between <strong>Dark</strong> and <strong>Light</strong> themes.</li></ul><h4 id="log-filter-categories" tabindex="-1">Log Filter Categories <a class="header-anchor" href="#log-filter-categories" aria-label="Permalink to “Log Filter Categories”">​</a></h4><p>Pill tabs at the top of the feed allow instant filtering by event type with live count badges:</p><ul><li><strong>All</strong>: Displays all recorded logs sequentially.</li><li><strong>Group</strong>: Shows execution segment boundaries, form URL matching blocks, and loop cycles.</li><li><strong>Success</strong>: Highlights successful field matches, inputs, and completed automated actions.</li><li><strong>Warn</strong>: Identifies non-critical warnings or skipped field conditions.</li><li><strong>Error</strong>: Immediately flags missing DOM elements, timeout errors, and submission failures.</li></ul><h4 id="detailed-log-cards" tabindex="-1">Detailed Log Cards <a class="header-anchor" href="#detailed-log-cards" aria-label="Permalink to “Detailed Log Cards”">​</a></h4><p>Each log entry is rendered as an interactive card containing:</p><ul><li><strong>Status &amp; Segment Badges</strong>: Clear badges denoting level (<code>SUCCESS</code>, <code>WARN</code>, <code>ERROR</code>, <code>GROUP</code>) and active segments (e.g. <code>{ENTRY-ALL-DONE}</code>).</li><li><strong>Precise Timing</strong>: Exact timestamp down to the second, plus relative execution duration badges (e.g. <code>+1.00s</code>).</li><li><strong>One-Click Copy</strong>: Copy card contents and diagnostic payload directly to your clipboard.</li><li><strong>Source URL</strong>: Clickable link to the exact web page where the event occurred.</li></ul><hr><h3 id="performance-settings" tabindex="-1">Speed &amp; Performance <a class="header-anchor" href="#performance-settings" aria-label="Permalink to “Speed &amp; Performance”">​</a></h3><p>Configure automation execution speed, DOM navigation monitoring, and layout positions.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Description</th><th>Default / Options</th></tr></thead><tbody><tr><td><strong>Status Bar Position</strong></td><td>Dropdown</td><td>Sets the placement of the floating status bar on the page.</td><td><code>Bottom</code>, <code>Top</code></td></tr><tr><td><strong>URL Change Monitoring Mode</strong></td><td>Dropdown</td><td>Choose how the extension detects and handles page navigation or dynamic URL transitions.</td><td><code>SPA / Dynamic History changes (Sync)</code></td></tr><tr><td><strong>Form Filling Speed</strong></td><td>Dropdown</td><td>Controls execution delay between sequential field actions.</td><td><code>Fast (Instant execution)</code></td></tr></tbody></table><h4 id="url-change-monitoring-modes" tabindex="-1">URL Change Monitoring Modes <a class="header-anchor" href="#url-change-monitoring-modes" aria-label="Permalink to “URL Change Monitoring Modes”">​</a></h4><table tabindex="0"><thead><tr><th>Mode</th><th>Best Used For</th></tr></thead><tbody><tr><td><strong>SPA / Dynamic History changes (Sync)</strong></td><td>Single Page Applications (React, Vue, Angular) where the URL updates dynamically via the History API without a full page reload.</td></tr><tr><td><strong>SPA / Dynamic History changes (Async)</strong></td><td>Complex SPAs that render DOM elements asynchronously after a URL route or hash transition.</td></tr><tr><td><strong>Standard Page reloads (Sync)</strong></td><td>Traditional multi-page web applications that perform full page reloads on navigation.</td></tr></tbody></table><h4 id="form-filling-speed-options" tabindex="-1">Form Filling Speed Options <a class="header-anchor" href="#form-filling-speed-options" aria-label="Permalink to “Form Filling Speed Options”">​</a></h4><table tabindex="0"><thead><tr><th>Speed Option</th><th>Behavior</th></tr></thead><tbody><tr><td><strong>Fast (Instant execution)</strong></td><td>Fills fields sequentially with zero artificial delay for maximum automation throughput.</td></tr><tr><td><strong>Medium (0.3s delay)</strong></td><td>Adds a 300ms delay between field operations to ensure reactive input handlers register values.</td></tr><tr><td><strong>Slow (2s delay)</strong></td><td>Adds a 2-second delay between field operations for slow web forms or visual demonstrations.</td></tr><tr><td><strong>Randomized delay range</strong></td><td>Introduces human-like randomized delays between fields within a configurable range.</td></tr></tbody></table><h4 id="random-speed-settings" tabindex="-1">Randomized Delay Range Settings <a class="header-anchor" href="#random-speed-settings" aria-label="Permalink to “Randomized Delay Range Settings”">​</a></h4><p>When <strong>Randomized delay range</strong> is selected, the following duration parameters appear:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th><th>Example Value</th></tr></thead><tbody><tr><td><strong>Min Delay (ms)</strong></td><td>Number</td><td>Minimum delay time in milliseconds.</td><td><code>200</code></td></tr><tr><td><strong>Max Delay (ms)</strong></td><td>Number</td><td>Maximum delay time in milliseconds.</td><td><code>1000</code></td></tr></tbody></table><hr><h3 id="environment-settings" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-settings" aria-label="Permalink to “Environment Variables”">​</a></h3><p>Configure global variables accessible in expressions, templates, and field values using <code>{$key_name$}</code> syntax.</p><img src="/image/global-env-var.png" alt="Environment Variables" style="max-width:100%;width:680px;height:auto;border-radius:8px;margin:12px 0;"><p><strong>Key Features:</strong></p><ul><li><strong>Table &amp; JSON Views</strong>: Switch seamlessly between a structured table view and a direct JSON editor.</li><li><strong>Search by Key</strong>: Quickly locate variables using the search filter.</li><li><strong>Data Types</strong>: Supports typed values such as <code>String</code>, <code>Number</code>, <code>Boolean</code>, and <code>Object</code>.</li><li><strong>Row Actions</strong>: Copy value, duplicate variable row, or delete variable.</li></ul><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Variable Key</strong></td><td>The unique identifier used to reference the variable (e.g. <code>title</code>).</td></tr><tr><td><strong>Type</strong></td><td>The variable data type (<code>String</code>, <code>Number</code>, etc.).</td></tr><tr><td><strong>Value</strong></td><td>The value assigned to the variable.</td></tr><tr><td><strong>Actions</strong></td><td>Quick action buttons to copy, duplicate, or delete the variable.</td></tr></tbody></table><p><strong>Usage Example:</strong></p><p>Reference environment variables in field values or settings using curly brackets:</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">$title$</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Site-Specific Environment Variables</p><p>Variables defined here apply <strong>globally</strong> across all websites. If you need variables isolated to a specific website, configure <a href="/documentation/site/site-settings.html#site-environment-variables">Site Environment Variables</a> inside that site&#39;s settings. Site-level variables automatically take precedence if the same key name is used.</p></div><hr><h3 id="captcha-solution" tabindex="-1">Auto-Solve CAPTCHAs <a class="header-anchor" href="#captcha-solution" aria-label="Permalink to “Auto-Solve CAPTCHAs”">​</a></h3><p>Configure automated CAPTCHA solving services to bypass verification challenges during form filling cycles.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>Auto-Solve CAPTCHAs</strong></td><td>Toggle</td><td><strong>Master Switch</strong>. Bypass verification challenges automatically during form filling cycles.</td></tr><tr><td><strong>Service</strong></td><td>Provider</td><td>Supported CAPTCHA solving provider (e.g. <code>2Captcha</code>).</td></tr><tr><td><strong>API Key</strong></td><td>Secret Key</td><td>Your provider account API key (with visibility toggle to reveal/hide).</td></tr><tr><td><strong>Solve Cloudflare Turnstile challenges</strong></td><td>Toggle</td><td>Automatically detect and solve Cloudflare Turnstile verification challenges.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Get API Key</p><p>Obtain your API key from your <a href="https://2captcha.com/" target="_blank" rel="noreferrer">2Captcha</a> account dashboard.</p></div><div class="info custom-block"><p class="custom-block-title">Priority Hierarchy</p><p>CAPTCHA settings can be configured at three levels:</p><ol><li><strong>Field Settings</strong> (Highest Priority)</li><li><strong>Site Settings</strong></li><li><strong>Global Settings</strong> (Configured here)</li></ol></div><h4 id="captcha-related-docs" tabindex="-1">Related Documentation <a class="header-anchor" href="#captcha-related-docs" aria-label="Permalink to “Related Documentation”">​</a></h4><ul><li><a href="/documentation/field-types/captcha-solution.html">Captcha Solution Field Type</a></li><li><a href="/documentation/field-types/captcha-solution/2captcha.html">2Captcha Documentation</a></li></ul><hr><h3 id="web-request-monitoring" tabindex="-1">Monitored Request URLs (Match Patterns) <a class="header-anchor" href="#web-request-monitoring" aria-label="Permalink to “Monitored Request URLs (Match Patterns)”">​</a></h3><p>Specify URL match patterns to track network requests across targeted domains.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>Monitored Request URLs</strong></td><td>Tag Input</td><td>Enter URL match patterns (e.g. <code>https://*/*</code>) and press <kbd>Enter</kbd>.</td></tr></tbody></table><p><strong>Match Pattern Examples:</strong></p><ul><li><code>https://*/*</code> — Targets all HTTPS domains.</li><li><code>*://mail.google.com/*</code> — Targets Gmail specifically.</li></ul><div class="info custom-block"><p class="custom-block-title">Note</p><p>Used by the <a href="/documentation/field-types/web-request-completed.html"><code>Web Request Completed</code></a> and <a href="/documentation/field-types/request-monitor.html"><code>Request Monitor</code></a> field types to monitor and capture background HTTP requests.</p></div><hr><h2 id="microsoft-form" tabindex="-1"><img src="/svg/template.svg" class="doc-icon" width="22" height="22" alt="Microsoft Form Rules"> Microsoft Form Rules <a class="header-anchor" href="#microsoft-form" aria-label="Permalink to “Microsoft Form Rules”">​</a></h2><p>Configure Microsoft Forms integration and field selector customization for optimal compatibility.</p><table tabindex="0"><thead><tr><th>Field Options</th><th>Description</th><th>Example Values</th></tr></thead><tbody><tr><td><strong>Import Settings</strong></td><td>Import Microsoft Form configuration</td><td>JSON configuration file</td></tr><tr><td><strong>Export Settings</strong></td><td>Export current Microsoft Form settings</td><td>Downloadable settings file</td></tr><tr><td><strong>Custom Selector Query</strong></td><td>Override default field selectors when they don&#39;t work</td><td><code>input[name=&quot;fieldName&quot;]</code>, <code>#customField</code></td></tr></tbody></table><p><strong>How to Use:</strong></p><ol><li><strong>Import Settings</strong>: Upload a previously exported Microsoft Form configuration</li><li><strong>Export Settings</strong>: Download current settings for backup or sharing</li><li><strong>Custom Selector Query</strong>: Enter custom CSS selectors for problematic fields</li></ol><hr><h2 id="extension-server" tabindex="-1"><img src="/svg/system.svg" class="doc-icon" width="22" height="22" alt="Local Extension Server"> Local Extension Server <a class="header-anchor" href="#extension-server" aria-label="Permalink to “Local Extension Server”">​</a></h2><p>Configure the connection to your local server to enable advanced automation features, such as email operations and local data processing. See <a href="/documentation/local-server/local-server.html">Local Server</a> for more details.</p><img src="/image/local-server-01.png" height="400" width="400" alt="Extension Server Settings"><h3 id="server-details" tabindex="-1">Server Details <a class="header-anchor" href="#server-details" aria-label="Permalink to “Server Details”">​</a></h3><p>Manage your local server authentication and monitor connection health.</p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>X-API-Token</strong></td><td>Enter the API token provided by your local server. You can generate this at <a href="http://127.0.0.10:8080/settings/api" target="_blank" rel="noreferrer">http://127.0.0.10:8080/settings/api</a>.</td></tr><tr><td><strong>Check Server Status</strong></td><td>Click this button to verify if the extension can communicate with your local server.</td></tr><tr><td><strong>Remove server connection</strong></td><td>Click this to clear the API token and disconnect from the local server.</td></tr></tbody></table><p><strong>Connection Status:</strong> The settings page displays &quot;Server is Connected: Yes/No&quot; in real-time to indicate the current status of the link between the extension and your local server.</p><p><strong>Response Details:</strong> When you check the server status, a detailed JSON response from the server is displayed, allowing you to verify the server&#39;s health and uptime.</p><hr><h2 id="export-import" tabindex="-1"><img src="/svg/database.svg" class="doc-icon" width="22" height="22" alt="Export / Import Data"> Export / Import Data (Data Management &amp; Backups) <a class="header-anchor" href="#export-import" aria-label="Permalink to “Export / Import Data (Data Management &amp; Backups)”">​</a></h2><p>The <strong>Data Management &amp; Backups</strong> dashboard provides centralized controls to export, import, and manage your extension configurations across different browsers or backup storage.</p><h3 id="import-site-configurations" tabindex="-1">Import Site Configurations <a class="header-anchor" href="#import-site-configurations" aria-label="Permalink to “Import Site Configurations”">​</a></h3><p>Restore previously saved site configurations, form definitions, and field rules from a JSON backup file.</p><table tabindex="0"><thead><tr><th>Action</th><th>Control</th><th>Description</th></tr></thead><tbody><tr><td><strong>Choose JSON File to Import</strong></td><td>File Upload Button</td><td>Select an exported <code>.json</code> configuration file from your computer to restore your site definitions and field mappings.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Safe Import</p><p>Importing a JSON configuration updates and merges existing site configurations without wiping unrelated extension settings.</p></div><h3 id="export-site-backup" tabindex="-1">Export Site Backup <a class="header-anchor" href="#export-site-backup" aria-label="Permalink to “Export Site Backup”">​</a></h3><p>Export your configurations into standardized <code>.json</code> backup files for safe keeping, version control, or migrating to another browser profile.</p><table tabindex="0"><thead><tr><th>Action</th><th>Format</th><th>Description</th></tr></thead><tbody><tr><td><strong>Backup All Sites</strong></td><td><code>.json</code> File</td><td>Save all active sites, registered forms, and field configurations into a single JSON backup.</td></tr><tr><td><strong>Backup Archived Sites</strong></td><td><code>.json</code> File</td><td>Save all archived sites and inactive forms into a separate dedicated JSON backup file.</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Note</p><p>Backup files contain site definitions, form structures, field rules, and selector configurations. Backups do not include uploaded <code>.xlsx</code> spreadsheet rows, which are managed independently per session.</p></div><h3 id="danger-zone" tabindex="-1">Danger Zone <a class="header-anchor" href="#danger-zone" aria-label="Permalink to “Danger Zone”">​</a></h3><p>Permanent deletion actions to wipe site storage. Exercise extreme caution when using these options.</p><table tabindex="0"><thead><tr><th>Action</th><th>Severity</th><th>Description</th></tr></thead><tbody><tr><td><strong>Delete All Sites</strong></td><td>Critical</td><td>Permanently wipes all active site configurations, forms, and fields from extension storage.</td></tr><tr><td><strong>Delete Archived Sites</strong></td><td>Critical</td><td>Permanently wipes all archived sites and stored historical configurations from extension storage.</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Irreversible Actions</p><ul><li><strong>Always Backup First</strong>: Generate a <strong>Backup All Sites</strong> JSON export before deleting any configurations.</li><li><strong>Permanent Loss</strong>: Deleted configurations cannot be recovered once removed from storage.</li><li><strong>Prefer Archiving</strong>: If a site is no longer actively needed, move it to the Archive rather than permanently wiping it.</li></ul></div>`,139)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};